-- CAPEX Actual Cost share of Plan
INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
SELECT 1000074,11,0,'Y',TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Actual Cost share of Plan','SUM(ProjectBalanceAmt) / SUM(PlannedAmt) in the context currency; no value when the plan sum is not above 0','SELECT ROUND(CASE WHEN SUM(p.PlannedAmt)>0 THEN SUM(p.ProjectBalanceAmt) * 1.0 / SUM(p.PlannedAmt) END, 6) FROM C_Project p','WHERE p.C_Currency_ID=@$C_Currency_ID@','p.Created','p.AD_Org_ID','p.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'A','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010074' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000074)
;
