SELECT 1000075,11,0,'Y',TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Budget Actual Overrun','sum of cost minus plan over the active over-budget projects, context currency','SELECT SUM(COALESCE(p.ProjectBalanceAmt,0)-COALESCE(p.PlannedAmt,0)) FROM C_Project p','WHERE p.IsActive=''Y'' AND p.Processed=''N'' AND COALESCE(p.ProjectBalanceAmt,0)<>0 AND COALESCE(p.ProjectBalanceAmt,0)>COALESCE(p.PlannedAmt,0) AND p.C_Currency_ID=@$C_Currency_ID@','p.Created','p.AD_Org_ID','p.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'A','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010075' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000075)
;
