-- CAPEX Forecast Cost at Completion (proposed)
INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
SELECT 1000076,11,0,'Y',TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Forecast Cost at Completion (proposed)','Q3 proposed: EAC = Spent + (Budget - Done) * Spent / Done over active projects with Spent and Done above 0, context currency','SELECT ROUND(SUM(p.ProjectBalanceAmt + (COALESCE(p.PlannedAmt,0) - (SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')) * p.ProjectBalanceAmt * 1.0 / (SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')), 6) FROM C_Project p','WHERE p.IsActive=''Y'' AND p.Processed=''N'' AND p.ProjectBalanceAmt>0 AND (SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')>0 AND p.C_Currency_ID=@$C_Currency_ID@','p.Created','p.AD_Org_ID','p.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'A','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010076' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000076)
;
INSERT INTO PA_Measure (PA_Measure_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,MeasureType,MeasureDataType,PA_MeasureCalc_ID,PA_Measure_UU)
SELECT 1000076,11,0,'Y',TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Forecast Cost at Completion (proposed)','Q3 proposed: EAC = Spent + (Budget - Done) * Spent / Done over active projects with Spent and Done above 0, context currency','C','S',1000076,'5a0c3e1e-0b7d-4c1e-9f3a-cafe00020076' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_Measure WHERE PA_Measure_ID=1000076)
;
-- CAPEX Forecast basis differs (proposed)
INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
SELECT 1000077,11,0,'Y',TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Forecast basis differs (proposed)','active projects with Spent and Done above 0 whose CPI = Done / Spent lies outside 0.5 .. 2 (Spent and Done not on one basis)','SELECT COUNT(*) FROM C_Project p','WHERE p.IsActive=''Y'' AND p.Processed=''N'' AND p.ProjectBalanceAmt>0 AND (SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')>0 AND ((SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'') * 1.0 / p.ProjectBalanceAmt < 0.5 OR (SELECT SUM(ph.PlannedAmt) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'') * 1.0 / p.ProjectBalanceAmt > 2)','p.Created','p.AD_Org_ID','p.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'A','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010077' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000077)
;
