SELECT 1000079,11,0,'Y',TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Verified Cost (proposed)','Q4 proposed: ProjectBalanceAmt of projects with a processed Project Issue, context currency (overlaps Actual Cost)','SELECT SUM(p.ProjectBalanceAmt) FROM C_Project p','WHERE p.C_Currency_ID=@$C_Currency_ID@ AND EXISTS (SELECT 1 FROM C_ProjectIssue i WHERE i.C_Project_ID=p.C_Project_ID AND i.Processed=''Y'')','p.Created','p.AD_Org_ID','p.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'A','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010079' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000079)
