-- CAPEX Ready for Handover (proposed)
INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
SELECT 1000086,11,0,'Y',TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-13 13:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Ready for Handover (proposed)','active projects with at least one phase and every phase complete','SELECT COUNT(*) FROM C_Project p','WHERE p.IsActive=''Y'' AND p.Processed=''N'' AND EXISTS (SELECT 1 FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID) AND NOT EXISTS (SELECT 1 FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND COALESCE(ph.IsComplete,''N'')<>''Y'')','p.Created','p.AD_Org_ID','p.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'A','5a0c3e1e-0b7d-4c1e-9f3a-cafe00010086' FROM dual WHERE NOT EXISTS (SELECT 1 FROM PA_MeasureCalc WHERE PA_MeasureCalc_ID=1000086)
;
